smask = (texture(sampler_pw_noise_lq,uv4 / 256.0)).g-.95;
stars += pow(clamp01(2.0 / n/length(abs(fract(uv4)-.5))*smask), 2.0 );
}
//distant light
ret += bdist*bdist*vec3( 0.0 ,.05,.1);
ret += (2.0 * stars*stars) * sat(bdist * 16.0-15);
ret = vec3( 1.0 ) - exp((-2)*ret);
